package com.studenttong.mobile;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.location.*;import android.os.*;import org.json.*;
public final class MockLocationService extends Service implements MockLocationManager.Events {
 public static final String START="start",PAUSE="pause",RESUME="resume",STOP="stop";final Handler h=new Handler(Looper.getMainLooper());Store store;MockLocationManager engine;MockLocationConfig config;String phase="stopped",session="",provider="";long started;JSONObject last;boolean cleaning;
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();store=new Store(this);NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("mock-location","系统模拟定位",NotificationManager.IMPORTANCE_LOW));}
 public int onStartCommand(Intent i,int flags,int startId){if(i==null){stopSelf();return START_NOT_STICKY;}String action=i.getAction(),owner=i.getStringExtra("aid");if(owner==null){if(config==null)stopSelf();return START_NOT_STICKY;}if(config!=null&&(!config.aid.equals(owner)||START.equals(action)))return START_NOT_STICKY;if(config==null&&(PAUSE.equals(action)||RESUME.equals(action))){stopSelf();return START_NOT_STICKY;}try{JSONObject existing=LocationModeManager.runtime(this);if(config!=null&&!config.aid.equals(owner))throw new Exception("模拟定位属于其他账号，请先在原账号停止");if(config==null&&existing.has("aid")&&!owner.equals(existing.optString("aid"))&&existing.optBoolean("registered")){stopSelf();return START_NOT_STICKY;}if(STOP.equals(action)){if(config==null){recover(existing,owner);phase="stopped";write("已停止；仅清理本模块的测试Provider",null);}else finishRun("stopped","模拟定位已停止");stopSelf();return START_NOT_STICKY;}
 if(START.equals(action)){if(config!=null)throw new Exception("请先停止当前模拟");recover(existing,owner);config=new MockLocationConfig(new JSONObject(i.getStringExtra("config")));if(!config.aid.equals(owner))throw new Exception("账号不匹配");store.account(owner);if(!LocationModeManager.authorized(this))throw new Exception("请在开发者选项选择学生通为模拟位置应用");if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=0)throw new Exception("请先授予精确定位权限");store.setSetting(config.aid,"location.lastMockConfig",config.json().toString());started=System.currentTimeMillis();session=java.util.UUID.randomUUID().toString();foreground("正在准备系统模拟定位");begin();}
 else if(PAUSE.equals(action)&&config!=null){closeEngine();phase="paused";write("已暂停并移除测试Provider，正常定位可用",null);notifyState("学生通模拟定位已暂停");}
 else if(RESUME.equals(action)&&config!=null){if(!phase.equals("paused"))throw new Exception("当前不能恢复");begin();}
 }catch(Exception e){phase="error";try{closeEngine();}catch(Exception ignored){}write(e.getMessage()==null?"模拟定位操作失败":e.getMessage(),null);if(config!=null)saveCorrection(e.getMessage());stopForeground(true);stopSelf();}return START_NOT_STICKY;}
 void recover(JSONObject old,String owner)throws Exception{if(!old.optBoolean("registered"))return;if(!owner.equals(old.optString("aid")))throw new Exception("请由原账号清理未完成模拟");String p=old.optString("provider");if(!p.matches("studenttong_[a-f0-9]{32}"))throw new Exception("Provider记录无效，未删除任何系统Provider");LocationManager m=(LocationManager)getSystemService(LOCATION_SERVICE);if(m.getAllProviders().contains(p))m.removeTestProvider(p);old.put("registered",false).put("state","stopped").put("message","已清理上次中断的本模块Provider");store.setSetting("_global","location.runtime",old.toString());}
 void begin()throws Exception{if(!LocationModeManager.authorized(this))throw new Exception("模拟定位授权已撤销");phase="starting";last=null;engine=new MockLocationManager(this,config,this);provider=engine.provider;write("等待系统回读并验证Mock标记",null);engine.begin();write(phase.equals("running")?"系统已回读对应坐标，Mock标记为是":"等待系统回读并验证Mock标记",last);h.removeCallbacks(pulse);h.postDelayed(pulse,config.interval);}
 final Runnable pulse=new Runnable(){public void run(){if(engine==null||!engine.registered()||config==null||!phase.equals("running")&&!phase.equals("starting"))return;if(!LocationModeManager.authorized(MockLocationService.this)||checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=0){failure("系统定位或模拟授权已撤销");return;}engine.publish();if(phase.equals("starting")&&System.currentTimeMillis()-started>15000){failure("未从系统读回匹配的Mock位置，未报告运行成功");return;}if(phase.equals("running")&&last!=null&&System.currentTimeMillis()-last.optLong("time")>15000){failure("系统位置回读已过期");return;}if(engine!=null)h.postDelayed(this,config.interval);}};
 public void read(Location l){try{last=LocationModeManager.fix(l);boolean changed=!phase.equals("running");phase="running";write("系统已回读对应坐标，Mock标记为是",last);if(changed)notifyState("学生通模拟定位运行中");}catch(Exception e){failure("系统定位回读解析失败");}}
 public void failure(String reason){if(cleaning)return;try{finishRun("error",reason);}catch(Exception ignored){}stopSelf();}
 void write(String message,JSONObject fix){try{JSONObject prior=LocationModeManager.runtime(this);String owner=config==null?prior.optString("aid"):config.aid;JSONObject j=new JSONObject().put("aid",owner).put("state",phase).put("provider",provider.isEmpty()?prior.optString("provider"):provider).put("registered",engine!=null&&engine.registered()).put("heartbeatElapsed",SystemClock.elapsedRealtime()).put("updated",System.currentTimeMillis()).put("message",message).put("session",session).put("started",started).put("interval",config==null?2000:config.interval);if(fix!=null)j.put("fix",fix);else if(last!=null)j.put("fix",last);store.setSetting("_global","location.runtime",j.toString());}catch(Exception ignored){}}
 void closeEngine()throws Exception{h.removeCallbacks(pulse);if(engine!=null){engine.close();engine=null;}}
 void finishRun(String state,String message)throws Exception{cleaning=true;try{closeEngine();phase=state;write(message,last);saveCorrection(message);stopForeground(true);}finally{cleaning=false;}}
 void saveCorrection(String message){if(config==null||session.isEmpty())return;try{JSONObject r=new JSONObject().put("id",session).put("before",config.before).put("selected",config.point.json()).put("reason",config.reason).put("started",started).put("ended",System.currentTimeMillis()).put("accuracy",config.point.accuracy).put("state",phase).put("message",message);new LocationHistoryManager(store,config.aid).add("corrections",r);}catch(Exception ignored){}}
 Notification notification(String text){Intent stop=new Intent(this,MockLocationService.class).setAction(STOP).putExtra("aid",config==null?LocationModeManager.runtime(this).optString("aid"):config.aid);PendingIntent action=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent open=new Intent(this,LocationMapActivity.class).putExtra("aid",config==null?"":config.aid).putExtra("diagnostics",true);PendingIntent content=PendingIntent.getActivity(this,2,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"mock-location").setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle(text).setContentText("系统Mock标记保留 · 点击停止可恢复正常定位").setContentIntent(content).setOngoing(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"停止",action).build()).build();}
 void foreground(String text){if(Build.VERSION.SDK_INT>=29)startForeground(300,notification(text),ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(300,notification(text));}void notifyState(String text){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(300,notification(text));}
 public void onTaskRemoved(Intent i){if(config!=null)try{finishRun("stopped","应用任务已移除，模拟定位已停止");}catch(Exception e){write("Provider清理失败，请重新授权后停止",null);}stopSelf();}
 public void onDestroy(){h.removeCallbacksAndMessages(null);if(engine!=null||config!=null&&phase.equals("paused"))try{finishRun("stopped","定位服务已退出");}catch(Exception e){phase="error";write("退出时清理失败，请在定位诊断中处理",null);}if(store!=null)store.close();super.onDestroy();}
}
